//! Pointed-tip study: small marks made with the point of a round sable or a
//! rigger, which should read at 1000px and at 3200px as the same marks
//! (same physical width and taper, no beads).
//!
//!   cargo paint study_tip                       1000px sheet
//!   cargo paint study_tip -- --full --crop 20,20,330,230     birds and rigging, 3200px
//!
//! Panels (units): birds (20..330, 20..230), rigging (340..660, 20..310),
//! signature (670..980, 60..300), grass (20..330, 360..650), twigs
//! (340..660, 340..650), spruce tips (670..980, 340..650).

use paint::{Gesture, Held, Mask, Paint, Rng, Style, Tool, Touch, hex};

fn main() {
    let o = paintings::run::Run::new("study_tip");
    let st = Style::friedrich();
    let mut rng = Rng::new(o.seed);
    let mut c = o.canvas(|| st.prepare(o.width, 1.5, o.seed));
    let h = c.height();

    // grounds for the marks: a pale evening sky above, a dull meadow below
    let sky = Mask::from_fn(c.frame(), |_, y| if y < 330.0 { 1.0 } else { 0.0 });
    let land = Mask::from_fn(c.frame(), |_, y| if y >= 330.0 { 1.0 } else { 0.0 });
    if o.stage("ground", &mut c, &mut rng) {
        c.work(&sky, &st.broad().color(|_, y| if y < 150.0 { hex("#b9c2c6") } else { hex("#e2d6b8") }).angle(|_, _| 0.0).coverage(2.5), 11);
        c.work(&land, &st.broad().color(|x, _| if x < 660.0 { hex("#8a8458") } else { hex("#a8a490") }).angle(|_, _| 0.0).coverage(2.5), 12);
        c.dry();
    }
    let dark = hex("#2a2620");
    let umber = hex("#3b2e22");
    let green = hex("#2f3a22");

    if o.stage("birds", &mut c, &mut rng) {
        // small birds: two wing flicks out from a body touch; a V is two
        // strokes pressed at the body and lifted off toward the wingtips
        let mut b = Held::new(Tool::round_sable(1.6), 1);
        for k in 0..9 {
            b.reload(Paint::body(dark), 0.8);
            let sz = 10.0 + 14.0 * rng.f();
            let (x, y) = (50.0 + (k % 3) as f32 * 95.0 + rng.range(-10.0, 10.0), 50.0 + (k / 3) as f32 * 60.0 + rng.range(-8.0, 8.0));
            let lift = rng.range(-0.4, 0.2);
            for side in [-1.0f32, 1.0] {
                let tip = (x + side * sz, y - sz * (0.35 + lift * side * 0.5));
                let mid = (x + side * sz * 0.45, y - sz * 0.35);
                c.drag(&mut b, &Gesture::new(vec![(x, y), mid, tip]).pressure(0.75, 0.0).ramps(0.1, 0.75).shake(0.6), None);
            }
            c.touch(&mut b, &Touch::at(x, y + 0.6).pressure(0.45), None);
        }
    }

    if o.stage("rigging", &mut c, &mut rng) {
        // a brig's masts and rigging: hairlines with a rigger, pressure light
        let mut hull = Held::new(Tool::round_sable(3.0), 2);
        hull.load(Paint::body(umber), 1.0);
        for k in 0..3 {
            let y = 280.0 + k as f32 * 5.0;
            c.drag(&mut hull, &Gesture::line((400.0 + k as f32 * 6.0, y), (600.0 - k as f32 * 8.0, y)).pressure(0.8, 0.8), None);
        }
        let mut rg = Held::new(Tool::rigger(0.5), 3);
        let masts = [(450.0f32, 60.0f32), (540.0, 80.0)];
        for &(mx, top) in &masts {
            rg.reload(Paint::body(umber), 1.0);
            c.drag(&mut rg, &Gesture::line((mx, 278.0), (mx + 3.0, top)).pressure(0.8, 0.5).ramps(0.02, 0.1).shake(0.4), None);
        }
        // stays and shrouds
        let lines = [
            ((450.0, 70.0), (380.0, 278.0)),
            ((450.0, 70.0), (410.0, 278.0)),
            ((450.0, 70.0), (543.0, 90.0)),
            ((543.0, 90.0), (620.0, 278.0)),
            ((543.0, 90.0), (590.0, 278.0)),
            ((452.0, 140.0), (543.0, 150.0)),
            ((452.0, 200.0), (420.0, 278.0)),
            ((542.0, 180.0), (570.0, 278.0)),
        ];
        for &(a, e) in &lines {
            rg.reload(Paint::body(dark), 0.6);
            c.drag(&mut rg, &Gesture::line(a, e).pressure(0.35, 0.3).ramps(0.05, 0.1).shake(0.3), None);
        }
        // yards: short strokes across the masts
        for &(mx, y, half) in &[(451.0f32, 110.0f32, 34.0f32), (451.0, 170.0, 44.0), (542.0, 125.0, 30.0), (541.5, 190.0, 40.0)] {
            rg.reload(Paint::body(umber), 1.0);
            c.drag(&mut rg, &Gesture::line((mx - half, y + 2.0), (mx + half, y - 1.0)).pressure(0.6, 0.6).ramps(0.1, 0.2).shake(0.4), None);
        }
    }

    if o.stage("signature", &mut c, &mut rng) {
        // a signature-like line: loops and hooks with pressure swelling on
        // the downstrokes and lifting to hairlines on the upstrokes
        let mut b = Held::new(Tool::round_sable(1.4), 4);
        b.load(Paint::body(dark), 1.0);
        let pts: Vec<(f32, f32)> = (0..90)
            .map(|i| {
                let t = i as f32 / 89.0;
                let x = 690.0 + t * 260.0 + (t * 40.0).sin() * 10.0;
                let y = 180.0 - (t * 20.0).cos() * 30.0 * (1.0 - 0.5 * t);
                (x, y)
            })
            .collect();
        let swell: Vec<f32> = (0..30).map(|i| if i % 3 == 1 { 1.0 } else { 0.35 }).collect();
        c.drag(&mut b, &Gesture::new(pts).pressure(0.8, 0.6).swell(swell).ramps(0.05, 0.2).shake(0.3), None);
        // an underline, flicked off
        b.reload(Paint::body(dark), 0.8);
        c.drag(&mut b, &Gesture::new(vec![(700.0, 250.0), (820.0, 256.0), (960.0, 244.0)]).pressure(0.8, 0.0).ramps(0.05, 0.8).shake(0.5), None);
    }

    if o.stage("grass", &mut c, &mut rng) {
        // blades flicked up from the root: pressed, then lifted off fast
        let mut b = Held::new(Tool::rigger(0.8), 5);
        let mut s = Held::new(Tool::round_sable(1.4), 6);
        for k in 0..70 {
            let hb = if k % 2 == 0 { &mut b } else { &mut s };
            hb.reload(Paint::body(if k % 3 == 0 { green } else { hex("#4a4a28") }), 0.7);
            let x = 40.0 + rng.f() * 270.0;
            let y = 620.0 + rng.range(-12.0, 12.0);
            let ht = 30.0 + 60.0 * rng.f();
            let lean = rng.range(-0.5, 0.5);
            let pts = vec![(x, y), (x + lean * ht * 0.3, y - ht * 0.5), (x + lean * ht, y - ht)];
            c.drag(hb, &Gesture::new(pts).pressure(0.8, 0.0).ramps(0.05, 0.85).shake(0.5), None);
        }
    }

    if o.stage("twigs", &mut c, &mut rng) {
        // bare twigs: each twig pressed where it leaves its limb and lifted
        // to its tip; side twigs from along it
        let mut b = Held::new(Tool::rigger(1.0), 7);
        let mut stack = vec![((500.0f32, 640.0f32), -1.57f32, 150.0f32, 0.9f32)];
        let mut n = 0;
        while let Some((p, a, len, pr)) = stack.pop() {
            n += 1;
            if n > 60 {
                break;
            }
            b.reload(Paint::body(umber), 0.8);
            let bend = rng.range(-0.3, 0.3);
            let pts: Vec<(f32, f32)> = (0..4)
                .map(|i| {
                    let t = i as f32 / 3.0;
                    let aa = a + bend * t;
                    (p.0 + aa.cos() * len * t, p.1 + aa.sin() * len * t)
                })
                .collect();
            let end = *pts.last().unwrap();
            c.drag(&mut b, &Gesture::new(pts.clone()).pressure(pr, 0.0).ramps(0.03, 0.8).shake(0.5), None);
            if len > 25.0 {
                for &f in &[0.45f32, 0.8] {
                    let q = (p.0 + (end.0 - p.0) * f, p.1 + (end.1 - p.1) * f);
                    let side = if rng.f() < 0.5 { -1.0 } else { 1.0 };
                    stack.push((q, a + side * rng.range(0.4, 0.8), len * rng.range(0.45, 0.6), pr * (1.0 - f * 0.6)));
                }
            }
        }
    }

    if o.stage("spruce", &mut c, &mut rng) {
        // spruce tips: a leader drawn up to a point, needle flicks hanging
        // off it to either side, shorter toward the top
        let mut b = Held::new(Tool::round_sable(1.2), 8);
        for &(x, base, ht) in &[(720.0f32, 640.0f32, 240.0f32), (820.0, 640.0, 280.0), (920.0, 640.0, 220.0)] {
            b.reload(Paint::body(green), 1.0);
            c.drag(&mut b, &Gesture::new(vec![(x, base), (x + 1.0, base - ht * 0.5), (x - 1.0, base - ht)]).pressure(0.9, 0.0).ramps(0.02, 0.6).shake(0.4), None);
            let n = 26;
            for i in 0..n {
                let t = i as f32 / n as f32;
                let y = base - ht * (0.08 + 0.9 * t);
                let reach = (1.0 - t) * 40.0 + 5.0;
                for side in [-1.0f32, 1.0] {
                    if i % 4 == 0 {
                        b.reload(Paint::body(green), 0.8);
                    }
                    let tip = (x + side * reach, y + reach * 0.35 + rng.range(-2.0, 2.0));
                    let mid = (x + side * reach * 0.5, y + reach * 0.05);
                    c.drag(&mut b, &Gesture::new(vec![(x, y), mid, tip]).pressure(0.7, 0.0).ramps(0.05, 0.8).shake(0.5), None);
                }
            }
        }
    }
    let _ = h;
    o.end(&mut c, &mut rng);
    c.relief(st.relief.0, st.relief.1);
    o.save(&mut c);
}
//! Running a painting from the command line: options, stages (timing,
//! stopping early to look, checkpoints to resume from), crop renders, and
//! the finishing recipe (varnish, cracks, raking light) paintings share.
//!
//!   cargo paint <name>                       1000px preview → out/<name>.png
//!   cargo paint <name> -- --full             3200px         → out/<name>_full.png
//!   cargo paint <name> -- --width 1600 --seed 7 --out path.png
//!   cargo paint <name> -- --full --crop 600,380,760,500
//!                                            only that window (units), at full
//!                                            resolution → out/<name>_full_crop.png
//!   cargo paint <name> -- --stop sky         save right after the "sky" stage
//!   cargo paint <name> -- --ckpt             save a checkpoint after every stage
//!   cargo paint <name> -- --resume mist      start from the "mist" checkpoint
//!   cargo paint <name> -- --resume mist --stop mist
//!                                            save the "mist" checkpoint as an image
//!   cargo paint <name> -- --resume mist --stale-ok --ckpt
//!                                            use a stale checkpoint and adopt it
//!   cargo paint <name> -- --no-cracks        skip craquelure in the finish
//!
//! Stage names on the command line match whatever the case, and spaces,
//! underscores and hyphens are the same (`--stop far_range` stops at "far
//! range"). A `--stop` or `--resume` naming no stage is an error that lists
//! the stages (before painting, when the painting names its stages with
//! string literals; otherwise when the run ends). `--stop` at the stage a
//! run resumes from saves that checkpoint as it is; at a stage before it,
//! it is an error.
//!
//! A painting is written as stages; each stage's painting goes inside its
//! block, so a resumed run can skip it:
//!
//! ```ignore
//! let o = Run::new("my_painting");
//! let mut rng = Rng::new(o.seed);
//! let mut c = o.canvas(|| st.prepare(o.width, 1.4, o.seed));
//! let sky = Mask::from_fn(c.frame(), ...);        // outside stages: always runs
//! if o.stage("sky", &mut c, &mut rng) {
//!     c.work(&sky, ...);                          // skipped when resuming later
//! }
//! let land = Mask::from_fn(c.frame(), ...);       // setup for "land": doesn't
//!                                                 // make "sky" stale
//! if o.stage("land", &mut c, &mut rng) { ... }
//! o.finish(&mut c, &mut rng, &Finish::aged(st.relief));
//! ```
//!
//! Rules for stages: paint only inside stage blocks (code between them runs
//! on every run, resumed or not, so keep it to masks, fields and constants,
//! and don't draw from the `Keep` state there: a resumed run would draw from
//! a different one); state that a stage hands to later ones travels in the
//! canvas or in the `Keep` value passed to `stage` (usually the painting's
//! `Rng`; pass the same one to `end` or `finish`, which close the last
//! stage). Geometry built from random draws between stages takes its own
//! `Rng::new(o.seed + k)`.
//!
//! Checkpoints (`--ckpt`) go to `out/<stem>.<stage>.ckpt` (stem of the output
//! file). One holds the whole canvas state after its stage, wet paint
//! included, plus the `Keep` state, the width, seed and crop, and
//! fingerprints of the code that produced it. `--resume` refuses a
//! checkpoint whose code has changed since (`--stale-ok` uses it anyway;
//! with `--ckpt` as well, it also rewrites the checkpoint's fingerprints for
//! the current code, so the next resume needs no `--stale-ok`).
//!
//! What counts as "the code that produced it" (the staleness model):
//! - the engine (`crates/paint/src`) and the helpers in `paintings/src`
//!   (not `bin`), whole: any edit there makes every checkpoint stale;
//! - in the painting's file, for a stage written `if o.stage(..) { .. }`:
//!   everything up to the closing brace of that block (its body and all
//!   that ran before it), and everything after the item that holds it
//!   (helper functions below `main`). Code after the block, between it and
//!   the next stage, is setup for later stages and doesn't count;
//! - minus code the painter marks as mattering only from a later stage on:
//!   a line ending in `// ckpt: from <stage>`, or the lines between a
//!   `// ckpt: from <stage>` line and a `// ckpt: end` line. Stages before
//!   <stage> leave them out; <stage> and later ones count them. That is the
//!   painter's word (a tagged constant a sky stage does read makes a stale
//!   sky look fresh); a tag naming no stage is an error.
//!
//! A stage call not directly followed by its block falls back to the old
//! rule: the source before the call that ends the stage, or both files
//! whole when that call is elsewhere (a `stage` in a loop is ended by
//! itself on the next iteration; its block is found, so this is rare).
//! Comments count as code here: editing one makes the stage stale.

mod source;

use paint::{Canvas, Cracks, Crop, Fbm, Pigment, Rgb, Rng, hex};
use std::cell::RefCell;
use std::panic::Location;
use std::path::{Path, PathBuf};
use std::time::Instant;

/// State a painting carries from stage to stage besides the canvas (saved in
/// checkpoints).
pub trait Keep {
    fn keep(&self) -> Vec<u8>;
    /// Restore from bytes `keep` wrote; an error (leaving `self` as it was)
    /// if they can't be its.
    fn restore(&mut self, b: &[u8]) -> Result<(), String>;
}

impl Keep for () {
    fn keep(&self) -> Vec<u8> {
        Vec::new()
    }
    fn restore(&mut self, b: &[u8]) -> Result<(), String> {
        if b.is_empty() { Ok(()) } else { Err(format!("{} bytes of state where none was kept", b.len())) }
    }
}

impl Keep for Rng {
    fn keep(&self) -> Vec<u8> {
        self.state().to_le_bytes().to_vec()
    }
    fn restore(&mut self, b: &[u8]) -> Result<(), String> {
        let b: [u8; 8] = b.try_into().map_err(|_| format!("{} bytes of state for an Rng (want 8)", b.len()))?;
        *self = Rng::from_state(u64::from_le_bytes(b));
        Ok(())
    }
}

impl<A: Keep, B: Keep> Keep for (A, B) {
    fn keep(&self) -> Vec<u8> {
        let a = self.0.keep();
        let mut v = (a.len() as u64).to_le_bytes().to_vec();
        v.extend(a);
        v.extend(self.1.keep());
        v
    }
    fn restore(&mut self, b: &[u8]) -> Result<(), String> {
        let (n, rest) = b.split_first_chunk::<8>().ok_or("state too short for a pair")?;
        let n = usize::try_from(u64::from_le_bytes(*n)).ok().filter(|&n| n <= rest.len()).ok_or("pair state is malformed")?;
        let (a, b) = rest.split_at(n);
        // restore both or neither
        let old = self.0.keep();
        self.0.restore(a)?;
        self.1.restore(b).inspect_err(|_| {
            let _ = self.0.restore(&old);
        })
    }
}

//! The air: one landscape (a sea horizon with ranges running out into it,
//! seen from a cliff top) under three skies, and a panel of ranges built
//! the old way beside the new. Everything is painted with brushes and
//! stipple by this study; the engine (`atmos`) only says how the one sun
//! lights the sky, the clouds and the air in front of the ranges.
//!
//!   1. morning: the sun low on the left, a cloud bank on the horizon, a
//!      few heaps, uneven haze and a haze layer
//!   2. overcast with a break: a stratus deck, the sun high on the right
//!      behind it, one break with the blue and a lit edge
//!   3. twilight after sunset: the sun 3.5° down ahead right; the Earth's
//!      shadow and the Belt of Venus opposite, the afterglow over the sun's
//!      place, high clouds lit from below
//!   4. ranges: left, the old way (even spacing in depth, parallel to the
//!      picture, similar peaks); right, `atmos::Ranges` (uneven spacing,
//!      oblique runs, peaks, domes, plateaus, saddles and cliffs, ranges
//!      that end, stratified haze and valley mist)
//!
//!   cargo paint study_sky
//!   cargo paint study_sky -- --fields          the engine's fields unpainted (a diagnostic)
//!   cargo paint study_sky -- --only morning     one panel
//!   cargo paint study_sky -- --full --crop 0,0,500,330

use paint::atmos::{Cloud, CloudField, Clouds, Haze, RangeLayer, Ranges, Sky, SkyField};
use paint::color::{Mix, mix};
use paint::form::Sample;
use paint::scene::{Sun, World};
use paint::{Canvas, Fbm, Form, Mask, Rgb, Stipple, Style, Tool, hex, smoothstep};

const PANEL_H: f32 = 300.0;
const GAP: f32 = 12.0;
const ASPECT: f32 = 1000.0 / (4.0 * PANEL_H + 3.0 * GAP);
/// Eye height (m): a cliff top over the sea.
const EYE: f32 = 30.0;

#[derive(Clone, Copy, PartialEq)]
enum Kind {
    Morning,
    Overcast,
    Twilight,
}

struct Panel {
    name: &'static str,
    kind: Kind,
    sun: Sun,
}

fn panels() -> [Panel; 3] {
    [
        Panel { name: "morning", kind: Kind::Morning, sun: Sun::deg(-19.0, 4.5) },
        Panel { name: "overcast", kind: Kind::Overcast, sun: Sun::deg(28.0, 24.0) },
        Panel { name: "twilight", kind: Kind::Twilight, sun: Sun::deg(14.0, -3.5) },
    ]
}

fn world(r: [f32; 4], sun: Sun) -> World {
    World::new(r, r[1] + r[3] * 0.6, EYE).fov(r[2], 58.0).sun(sun).visibility(30_000.0)
}

fn sky_for(kind: Kind, sun: Sun) -> Sky {
    match kind {
        Kind::Morning => Sky::new(sun).haze(2.6).uneven(0.6, 30_000.0, 11).layer(900.0, 500.0, 1.6, 0.8, 3),
        Kind::Overcast => Sky::new(sun).haze(3.5).uneven(0.4, 20_000.0, 5).overcast(0.25),
        Kind::Twilight => Sky::new(sun).haze(1.8).uneven(0.5, 40_000.0, 21),
    }
}

fn clouds_for(kind: Kind) -> Clouds {
    match kind {
        Kind::Morning => Clouds::new(vec![
            // a bank lying on the horizon, heavier on the right
            Cloud::bank(-2_000.0, 30_000.0, 38_000.0, 9_000.0, 700.0, 2_600.0, 4).density(0.035),
            // a few heaps, one near, uneven
            Cloud::cumulus(3_600.0, 10_000.0, 1_100.0, 2_600.0, 1_300.0, 8),
            Cloud::cumulus(-2_200.0, 16_000.0, 1_300.0, 1_600.0, 800.0, 9).soft(0.2),
            Cloud::stratus(3_800.0, 500.0, 0.34, 12).density(0.006).soft(0.5).wind(0.4, 5.0).reach(3_000.0, 40_000.0),
        ]),
        Kind::Overcast => Clouds::new(vec![Cloud::stratus(1_300.0, 700.0, 0.97, 31).density(0.02).soft(0.3).wind(-0.5, 1.6).heap(4_000.0).breaks(14_000.0, 0.22)]),
        Kind::Twilight => Clouds::new(vec![
            // high thin clouds, still in the sun
            Cloud::stratus(8_500.0, 700.0, 0.4, 41).density(0.004).soft(0.45).wind(0.2, 6.0).reach(8_000.0, 90_000.0),
            // low cloud already in the Earth's shadow
            Cloud::bank(-30_000.0, -6_000.0, 30_000.0, 8_000.0, 500.0, 1_500.0, 44).density(0.03),
        ]),
    }
}

fn haze_for(kind: Kind) -> Haze {
    match kind {
        Kind::Morning => Haze::new(28_000.0).height(900.0).mist(140.0, 6.0, 90.0, 7),
        Kind::Overcast => Haze::new(20_000.0).height(1200.0),
        Kind::Twilight => Haze::new(35_000.0).height(1000.0).mist(90.0, 4.0, 60.0, 9),
    }
}

/// The sea level's canvas y at distance z (m): a range's foot.
fn foot(w: &World, z: f32) -> f32 {
    w.horizon + w.focal * (w.eye + RangeLayer::curvature(z)) / z
}

/// The ranges' form: one Ridge per layer, nearer in front, lit by the sun.
fn range_form(c: &Canvas, w: &World, layers: &[RangeLayer]) -> (Form, Vec<u16>) {
    let mut form = Form::new(c.frame());
    let (x0, x1) = (w.view[0], w.view[0] + w.view[2]);
    let mut ids = vec![];
    for l in layers {
        let fy = foot(w, l.z_at(0.0)) + 2.0;
        let top = (0..=20).map(|i| l.crest(w, x0 + (x1 - x0) * i as f32 / 20.0)).fold(f32::MAX, f32::min);
        let ridge = l.ridge(w, x0, x1, (fy - top).max(4.0) + 4.0, 260.0).base(fy).z0(-(l.k as f32) * 5000.0);
        let d = l.z / 1000.0;
        ids.push(form.add_at(&ridge, &move |_, _, _| d));
    }
    let light = w.light();
    form.light(light);
    (form, ids)
}

/// The stone color of a range at a point (before the air): lit and shadow
/// families from the one sun, warm where the low sun finds it.
//! Stippling study: Friedrich's sky and mist technique [NG p.56; CATS p.127].
//!
//! Top: an evening sky laid in thin with a soft filbert in horizontal
//! strokes, then stippled in two passes (a coarser pass into the wet lay-in
//! aimed at the sky's tones, then, dry, a finer and lighter pass that grows
//! denser toward the glow at the horizon). The strip at the far left is the
//! lay-in alone, for comparison; the next strip has only the first pass.
//! Bottom: a dark ridge, let dry, with mist stippled over its foot, dense in the valley and thinning upward in banks.
//!
//!   cargo paint study_stipple                      1000px
//!   cargo paint study_stipple -- --full            3200px (compare crops)
//!   PAINT_DEBUG=1 ...                              touch counts and timings

use paint::{Mask, Stipple, Tool, Fbm, Style, hex, smoothstep};
use paint::color::{Mix, mix};

const ASPECT: f32 = 1.6;
const HORIZON: f32 = 390.0;
/// Left edges of the "lay-in only" and "first pass only" strips' ends.
const STRIP0: f32 = 120.0;
const STRIP1: f32 = 240.0;

fn main() {
    let run = paintings::run::Run::new("study_stipple");
    let st = Style::friedrich();
    let pal = &st.palette;
    let mut c = run.canvas(|| st.prepare(run.width, ASPECT, run.seed));
    let f = c.frame();
    let h = c.height();

    // the sky Friedrich might have wanted: cool blue-gray above, through a
    // pale greenish middle to a warm glow at the horizon
    let sky = |_x: f32, y: f32| {
        let t = (y / HORIZON).clamp(0.0, 1.0);
        paint::gradient(&[(0.0, hex("#6f84a8")), (0.45, hex("#a7b4bf")), (0.8, hex("#dcd4b8")), (1.0, hex("#ecd9a8"))], t, Mix::Light)
    };
    let ridge_top = move |x: f32| HORIZON - 40.0 + 30.0 * (x / 180.0).sin() * (x / 410.0).cos() - 25.0 * smoothstep(500.0, 900.0, x);
    let sky_m = Mask::from_fn(f, |_, y| 1.0 - smoothstep(HORIZON + 10.0, HORIZON + 20.0, y));

    let ridge_m = Mask::from_fn(f, move |x, y| smoothstep(ridge_top(x) - 1.5, ridge_top(x) + 1.5, y));

    if run.stage("lay-in", &mut c, &mut ()) {
        // ---- lay-in: thin paint, horizontal strokes, a shade darker and duller
        // than the sky will end
        let lay = st.broad().color(move |x, y| mix(sky(x, y), hex("#6a6f7a"), 0.07, Mix::Light)).angle(|_, _| 0.0).coverage(4.5).medium(0.25).dips(1, 0.6, 0.6);
        c.work(&sky_m, &lay, 11);
        if let Some(b) = st.blend() {
            c.work(&sky_m, &b.angle(|_, _| 0.0), 14);
        }
    }

    if run.stage("pass 1", &mut c, &mut ()) {
        // ---- first pass: a stippler of ~1 mm into the wet lay-in, aimed at
        // the sky's own tones; it breaks the strokes and fuses with the wet paint
        let pass1_m = sky_m.clone().mul_fn(|x, _| smoothstep(STRIP0, STRIP0 + 4.0, x));
        let s1 = Stipple::new(Tool::stippler(3.0))
            .mixed(pal, 0.45)
            .color(sky)
            .coverage(|_, _| 2.2)
            .pressure(0.5, 0.85)
            .dips(20, 0.4, 0.5);
        c.stipple(&pass1_m, &s1, 12);
        c.dry();
    }

    if run.stage("pass 2", &mut c, &mut ()) {
        // ---- second pass, dry: finer and lighter, denser toward the glow
        let pass2_m = sky_m.clone().mul_fn(|x, _| smoothstep(STRIP1, STRIP1 + 4.0, x));
        let glow = move |x: f32, y: f32| mix(sky(x, y), hex("#f2e2b4"), 0.06 + 0.22 * smoothstep(150.0, HORIZON, y), Mix::Light);
        let s2 = Stipple::new(Tool::stippler(1.6))
            .mixed(pal, 0.5)
            .color(glow)
            .coverage(|_, y| 2.2 * smoothstep(100.0, HORIZON, y))
            .pressure(0.5, 0.85)
            .dips(24, 0.35, 0.6);
        c.stipple(&pass2_m, &s2, 13);
        c.dry();
    }

    if run.stage("ridge", &mut c, &mut ()) {
        // ---- the ridge: dark, cool, laid in body paint
        let ridge = st.body().color(|_, y| mix(hex("#2c3336"), hex("#3a4038"), smoothstep(HORIZON, h, y), Mix::Pigment)).angle(|_, _| 0.1).angle_jitter(0.3).length(20.0, 50.0).coverage(5.0);
        c.work(&ridge_m, &ridge, 21);
        c.dry();
    }

    if run.stage("mist", &mut c, &mut ()) {
        // ---- mist over the foot of the ridge: banks thinning upward
        let banks = Fbm::new(31, 4, 220.0);
        let valley = h - 70.0;
        let mist_cov = move |x: f32, y: f32| {
            let up = (valley - y) / 150.0 + 0.35 * banks.get(x * 0.6, y * 2.5);
            (1.0 - smoothstep(0.0, 1.0, up)) * 3.0
        };
        let mist_m = ridge_m.clone().mul_fn(|x, _| smoothstep(STRIP0, STRIP0 + 4.0, x));
        let mist = Stipple::new(Tool::stippler(2.2))
            .mixed(pal, 0.7)
            .color(|_, _| hex("#c3c4bf"))
            .coverage(mist_cov)
            .pressure(0.5, 0.85)
            .dips(16, 0.3, 0.7)
            .aim(false);
        c.stipple(&mist_m, &mist, 22);
        c.dry();
    }

    run.end(&mut c, &mut ());
    c.relief(st.relief.0, st.relief.1);
    run.save(&mut c);
}

