fn ago(s: u64) -> String {
    match s {
        0..=119 => format!("{s}s"),
        120..=7199 => format!("{}min", s / 60),
        _ => format!("{}h", s / 3600),

    ///
    /// - Fine handwoven plain linen bought ready primed [KÖR p.283];
    ///   10–16 threads/cm (proxy, Eckersberg's Dresden canvases [CATS-E]).
    /// - Dresden grounds: 2–4 thin layers; lower ocher / red earth / chalk
    ///   layers "only served to smooth and even out the weave"; the top layer
    ///   brushed, its striations showing through the thin paint [KÖR p.284].
    ///   *Two Men Contemplating the Moon* has a reddish-ocher top ground used
    ///   as the mid-tone [KÖR p.284]. Ground total ~150–300 µm (proxy).
    /// - One or two very thin paint layers over a thin underpainting; skies,
    ///   mist and far hills stippled; paint pools in the ground texture
    ///   [CATS p.127; NG p.56].
    pub fn friedrich() -> Self {
        Style {
            name: "Caspar David Friedrich",
            width_mm: 440.0,
            linen: Linen { warp_per_cm: 15.0, weft_per_cm: 13.0, ..Linen::fine(1) },
            raw: hex("#a8966f"),
            ground: vec![
                Ground { color: hex("#9a5a36"), hiding: 0.8, um: 110.0, stiff: 0.25, apply: Apply::Knife { texture: 0.35 } },
                Ground { color: hex("#b08457"), hiding: 0.8, um: 70.0, stiff: 0.3, apply: Apply::Knife { texture: 0.3 } },
                Ground { color: hex("#a9785a"), hiding: 0.8, um: 60.0, stiff: 0.35, apply: Apply::Brush },
            ],
            broad: Tool { lay: 0.55, push: 0.03, ragged: 0.4, ..Tool::filbert(22.0) },
            body: Tool { lay: 0.7, push: 0.06, ..Tool::filbert(9.0) },
            detail: Tool::round_sable(2.2),
            line: Tool::rigger(0.6),
            blender: Some(Tool { pickup: 0.15, run: 45.0, ..Tool::badger(40.0) }),
            blend_passes: 3,
            blend_pressure: 0.5,
            palette: Palette::friedrich_1820(),
            body_medium: 0.2,
            thin_medium: 0.45,
            mix_jitter: 0.06,
            // Alice's pick from the Round 6 relief A/B (notes/round6/relief/):
            // 0.2 embossed every stroke into creases ("grooves"); 0.06 keeps
            // a hint of weave and ridge without them
            relief: (0.06, 0.006),
        }
    }

    /// Friedrich's early Berlin grounds (*Monk by the Sea*, *Abbey in the
    /// Oakwood*): bright red, then two light brown layers, the first two put
    /// on with a spatula, the third looking rolled on, with a finely
    /// textured structure he exploited [CATS p.127].
    pub fn friedrich_early() -> Self {
        Style {
            width_mm: 1714.0,
            linen: Linen { warp_per_cm: 12.0, weft_per_cm: 11.0, ..Linen::fine(1) },
            ground: vec![
                Ground { color: hex("#b0583a"), hiding: 0.85, um: 110.0, stiff: 0.25, apply: Apply::Knife { texture: 0.35 } },
                Ground { color: hex("#c9ad8a"), hiding: 0.8, um: 70.0, stiff: 0.3, apply: Apply::Knife { texture: 0.3 } },
                Ground { color: hex("#d8c7ab"), hiding: 0.8, um: 30.0, stiff: 0.5, apply: Apply::Roller },
            ],
            palette: Palette::friedrich_early(),
            ..Self::friedrich()
        }
    }

    /// A primed canvas as this painter bought or made it: linen of the
    /// painter's usual kind and physical size, and the ground layers.
    pub fn prepare(&self, width_px: usize, aspect: f32, seed: u64) -> Canvas {
        self.prepare_on(Canvas::new(width_px, aspect, self.raw), seed)
    }

    /// `prepare`, holding only the window `crop` (a crop render), whatever
    /// `set_crop` says.
    pub fn prepare_window(&self, width_px: usize, aspect: f32, seed: u64, crop: Option<crate::canvas::Crop>) -> Canvas {
        self.prepare_on(Canvas::new_window(width_px, aspect, self.raw, crop), seed)
    }

    fn prepare_on(&self, c: Canvas, seed: u64) -> Canvas {
        let mut c = c
            .with_size_mm(self.width_mm)
            .with_linen(Linen { seed, ..self.linen });
        for (k, g) in self.ground.iter().enumerate() {
            if g.um <= 0.0 {
                continue;
            }
            let s = seed * 31 + k as u64;
            match g.apply {
                Apply::Knife { texture } => c.prime(g.color, g.hiding, g.um, g.stiff, texture, s),
                Apply::Roller => c.prime(g.color, g.hiding, g.um, g.stiff, 0.8, s),
                Apply::Brush => {
                    brush_ground(&mut c, g, s);
                    // (`prime` counts its own layers)
                    c.ground_um += g.um;
                }
            }
        }
        c
    }
}

/// A brushed top ground, put on as a primer brushes out lead white in oil
/// (see notes/loop2_grain.md): the paste is first spread with a broad hog
/// brush in crossing strokes whose direction wanders over the canvas, then
/// laid off while wet with light passes of the unloaded brush held low, which
/// skim rather than plough, level the spreading's stroke edges and leave
/// only fine, broken bristle striations. (Before loop 2 the paste went on in
/// long, full, parallel strokes that set with their edge ridges a few mm
/// apart: a horizontal wood-grain under every thin sky. Ploughed ridges
/// were tall, sharp crests that thin sky paint drained off, leaving
/// one-pixel lines of bare ground.)
fn brush_ground(c: &mut Canvas, g: &Ground, s: u64) {
    let all = Mask::from_fn(c.frame(), |_, _| 1.0);
    let hog = Tool { lay: 1.2, ragged: 0.2, ..Tool::hog_flat(40.0) };
    let col = g.color;
    // the direction the primer works in drifts over the canvas, patch by
    // patch (~90 units = 40 mm; up to ±0.7 rad, across on average)
    let turn = move |x: f32, y: f32| 1.4 * (crate::surface::vnoise(x / 90.0, y / 90.0, s ^ 0x9e37) - 0.5);
    // the paste is pushed a little ahead of the bristles, not ploughed
    // into ridges (a hog's own push, 0.3, piled it 2x as thick at the
    // stroke edges: tall sharp crests the thin sky drained off)
    let spread = Handling::new(Tool { push: 0.15, ..hog.clone() })
        .color(move |_, _| col)
        .paint(g.hiding, g.stiff)
        .angle(turn)
        .angle_jitter(0.15)
        .cross(0.5)
        .curve(0.04, 0.3)
        .drift(0.25, 300.0)
        .tail(0.1)
        .broken(0.1)
        .swell(0.12)
        .length(100.0, 250.0)
        .coverage(3.5)
        .pressure(0.8, 0.95)
        .dips(1, (g.um / BRUSHED_UM_AT_FULL).powf(1.0 / BRUSHED_EXP).min(1.0), 0.3)
        .jitter(0.004, 0.002)
        .shake(0.15);
    c.work(&all, &spread, s);
    // laying off: the clean brush drawn lightly through the wet paste, held
    // low so it skims the paste and barely pushes it
    let lay_off = Handling::new(Tool { push: 0.03, ..hog })
        .blender()
        .angle(turn)
        .angle_jitter(0.12)
        .cross(0.15)
        .curve(0.06, 0.4)
        .drift(0.3, 250.0)
        .tail(0.2)
        .broken(0.3)
        .swell(0.25)
        .length(120.0, 380.0)
        .coverage(3.5)
        .pressure(0.35, 0.55)
        .dips(2, 0.0, 0.8)
        .shake(0.3);
    c.work(&all, &lay_off, s + 7);
    c.dry();
}

impl Style {
    /// Broad atmospheric passage (sky, fog, sea): long soft strokes of thin
    /// paint swung from the elbow, so they bow into long arcs and their
    /// direction wanders across the passage. Give it a direction (`angle`);
    /// the default is across the canvas.
    pub fn broad(&self) -> Handling<'_> {
        Handling::new(self.broad.clone())
            .length(80.0, 220.0)
            .coverage(2.5)
            .mixed(&self.palette, self.thin_medium)
            .mix_jitter(self.mix_jitter)
            .pressure(0.55, 0.8)
            .dips(2, 0.4, 0.5)
            .angle_jitter(0.06)
            .curve(0.06, 0.25)
            .drift(0.22, 350.0)
            .tail(0.15)
            .broken(0.08)
            .swell(0.18)
            .ramps(0.12, 0.4)
    }

    /// Building a form in body color: shorter strokes from the wrist, more
    /// bowed and broken, the direction wandering from patch to patch. Point
    /// them along the form (`angle`).
    pub fn body(&self) -> Handling<'_> {
        Handling::new(self.body.clone())
            .length(20.0, 60.0)
            .coverage(2.5)
            .mixed(&self.palette, self.body_medium)
            .mix_jitter(self.mix_jitter * 1.4)
            .pressure(0.6, 0.9)
            .dips(2, 0.56, 0.6)
            .angle_jitter(0.12)
            .curve(0.08, 0.3)
            .drift(0.3, 150.0)
            .tail(0.15)
            .broken(0.1)
            .swell(0.22)
    }

    /// Small forms and edges, cut in precisely.
    pub fn detail(&self) -> Handling<'_> {
        Handling::new(self.detail.clone())
            .length(4.0, 14.0)
            .coverage(3.0)
            .mixed(&self.palette, 0.1)
            .mix_jitter(self.mix_jitter)
            .pressure(0.7, 0.95)
            .dips(3, 0.9 * 0.8, 0.8)
            .clip(true)
            .threshold(0.1)
            .curve(0.04, 0.2)
            .drift(0.1, 60.0)
            .tail(0.1)
            .broken(0.0)
            .swell(0.2)
    }

    /// Short hatched strokes side by side, "like a closely woven textile"
    /// [NG pp.49–50]: conifers, grass, the texture of a far slope. One
    /// family of short, nearly straight strokes laid passage by passage; give
    /// them their direction (`angle`), or `cross` them.
    pub fn hatch(&self) -> Handling<'_> {
        Handling::new(Tool { width: self.detail.width * 1.2, ..self.detail.clone() })
            .length(5.0, 12.0)
            .coverage(2.5)
            .mixed(&self.palette, 0.15)
            .mix_jitter(self.mix_jitter)
            .pressure(0.6, 0.9)
            .dips(4, 0.7, 0.7)
            .angle_jitter(0.1)
            .curve(0.03, 0.1)
            .drift(0.15, 40.0)
            .tail(0.08)
            .broken(0.0)
            .swell(0.15)
            .clump(0.5)
            .ramps(0.05, 0.3)
    }

    /// A glaze or thin scumble brushed over dry paint: a soft brush, paint
    /// that is mostly medium (`medium` ≈ 0.85–0.95 for a transparent glaze,
    /// ≈ 0.6 for a veiling scumble), laid thinly in long strokes. Vary the
    /// depth with `load_at`; fuse it afterwards with `blend()`. The color is
    /// the glaze paint's masstone (not aimed: a veil's depth is the
    /// painter's to vary); add `.aim(coats)` to aim it at a look instead.
    pub fn glaze(&self, medium: f32) -> Handling<'_> {
        let soft = Tool { stiffness: 0.3, lay: 0.8, pickup: 0.08, ragged: 0.2, ..Tool::filbert(self.broad.width * 1.2) };
        Handling::new(soft)
            .mixed(&self.palette, medium)
            .by_masstone()
            .mix_jitter(self.mix_jitter * 0.5)
            .length(120.0, 300.0)
            .coverage(2.5)
            .pressure(0.5, 0.7)
            .dips(2, 0.35, 0.5)
            .angle_jitter(0.05)
            .curve(0.05, 0.25)
            .drift(0.2, 350.0)
            .tail(0.12)
            .broken(0.06)
            .swell(0.18)
            .ramps(0.2, 0.4)
    }

    /// Clean soft blender passes over a wet passage: light crossing strokes
    /// (± 0.2 rad to `angle`), worked top to bottom so the blender never
    /// drags paint back up a gradient (change with `order`/`sweep`).
    ///
    /// The blender stays inside the region it is given (`clip(true)`, soft
    /// where the mask is soft): a painter fusing a cut passage keeps the
    /// badger inside it, and an unclipped badger drags wet paint across the
    /// mask's edge, where later passages show it in their gaps. To fuse
    /// across an edge on purpose (softening a horizon), give it a mask that
    /// spans the edge, or `.clip(false)`.
    pub fn blend(&self) -> Option<Handling<'_>> {
        let t = self.blender.clone()?;
        Some(
            Handling::new(t)
                .length(120.0, 300.0)
                .coverage(3.0)
                .pressure(self.blend_pressure * 0.8, self.blend_pressure)
                .dips(3, 0.0, 0.9)
                .blender()
                .angle_jitter(0.05)
                .cross(0.2)
                .curve(0.06, 0.3)
                .drift(0.2, 300.0)
                .broken(0.0)
                .clip(true)
                .sweep(std::f32::consts::FRAC_PI_2),
        )
    }

    /// A brush held for lines.
    pub fn line_tool(&self, width: f32) -> Tool {
        Tool { width, length: width * 5.0, ..self.line.clone() }
    }

    /// Scumbling handling (not Friedrich's habit, for painters who use it).
    pub fn scumble(&self) -> Handling<'_> {
        Handling::new(self.body.clone()).scrub(3).mixed(&self.palette, 0.5).length(10.0, 20.0).orient(Orient::Across)
    }
}
# Color semantics (stream 1, branch `color`)

## The problem
A paint's color used to mean "how one coat looks over white":
`Pigment::with_hiding(color, hiding)` set the over-white look to `color` and
the over-black look to `color × hiding`. For any paint that doesn't fully hide,
the masstone (the paint laid thick) is darker than that. So a mark mixed to
match a field dried darker than the field, and a thin passage dried darker than
asked. The fresh painters hit this as dark stipple specks, darkened glazes and
recipe seams in the coast sky. They worked around it by sampling the canvas by
hand (`aim()` in `paintings/fresh/fresh_coast.rs`).

## What color means now
- **`Paint::color` and `Tube::color` are the masstone.** That is the paint
  laid thick, which is also how it looks laid over paint of the same color, at
  any thickness. In KM the masstone R∞ is the fixed point of compositing
  (`pigment::tests::masstone_is_a_fixed_point`). So a mark mixed to the field
  it sits in disappears into it, body color or thin.
- **Hiding is the contrast ratio of one coat** (look over black ÷ look over
  white; `pigment::hiding_of`). The same numbers as before (0.07 glaze, 0.5
  scumble, 0.92 body) now convert to one KM scattering value S per coat
  (`pigment::scatter_for`). S is flat across channels; absorption is
  `K = S·(1−R∞)²/(2R∞)` per channel, so it carries the hue
  (`Pigment::masstone`).
- **Mixing is two-constant KM with Mixbox for hue.** The masstone mixes in
  Mixbox latent space: in the wet layer by volume, on the palette by volume ×
  tinting strength (as before). S mixes linearly by volume (true KM). K follows
  from the mixed masstone and S. Before, hiding was mixed linearly and K/S was
  rebuilt from an over-white color. That under-weighted white: in real paint a
  little white makes a glaze turbid fast because its S is large, and linear
  S-mixing captures that. The wet layer's `Prop[0]` is now S, not hiding.
- **`Paint` carries S.** `Paint { color, scatter, stiff }`: the masstone and
  the KM scattering per coat. Name paint by hiding with
  `Paint::new(color, hiding, stiff)` or `p.with_hiding(h)`; `Paint::km`
  takes S directly; `p.hiding()` derives the contrast ratio for reporting.
  Hiding saturates near 1 (`scatter_for` caps it at 0.9995), so a paint that
  stored only hiding lost the S of any strongly scattering mixture: an
  opaque black + white pile mixed to 0.1 has S ≈ 20 and came back as S ≈ 1,
  and a 0.1-coat film of it over white read 0.44 instead of 0.10. Now the
  paint the brush loads is the paint the palette scored
  (`palette::canvas_tests::mixture_to_paint_preserves_scattering`).
- **Medium thins the pigment.** It multiplies K and S by (1 − medium) and
  leaves the masstone alone (`Mixture::paint`). The old rule was
  `hiding × k^0.6`.
- **Paints named by their tint** (glazes, as in "tints white to X") use
  `Paint::tint(tint, hiding, stiff)`. `Paint::glaze(tint)` calls it. The
  `Pigment::{transparent, semi, opaque, varnish, with_hiding}` constructors
  keep the over-white meaning for `Canvas::glaze` films. Grounds
  (`Canvas::prime`) now use masstone semantics like all other paint.

## Aim at the result
A painter judges a pile on the canvas: "what will this look like here, over
what is already painted, laid as thick as I lay it?" That question now has an
answer at three levels:

```rust
// what is on the canvas at a point (dry picture + wet paint, disc of radius r)
let under = c.under(x, y, r);
// preview: how a paint looks laid `coats` thick over it
let look = paint.over(under, coats);

// per mark (stipple, dabs, hand-made strokes): the pile from the palette
// that, thinned with `medium` and laid `coats` thick here, looks `want`
let p: Paint = c.aim(&pal, want, (x, y), r, medium, coats);
let m: Mixture = pal.aim(want, under, medium, coats);   // same, with the recipe
let p = pal.paint_for(want, under, medium, coats);       // same, as Paint
// no palette: solve the masstone for a fixed hiding
let p = Paint::aimed(want, under, coats, hiding, stiff);
// name paint by hiding, override on a mixed paint
let p = pal.paint(col, 0.0).with_hiding(0.97).with_stiff(1.0);

// handlings: palette-mixed handlings aim by default
st.broad().color(sky)                  // Aim::Laid: expects the thickness it lays
st.broad().color(sky).aim(0.8)         // expect 0.8 coats
